+
+function hexChannels(color: string): [number, number, number] | null {
+  const match = /^#([\da-f]{6})$/i.exec(color.trim());
+  if (!match) return null;
+  const value = match[1]!;
+  return [
+    Number.parseInt(value.slice(0, 2), 16),
+    Number.parseInt(value.slice(2, 4), 16),
+    Number.parseInt(value.slice(4, 6), 16),
+  ];
+}
+
+function linear(channel: number): number {
+  const normalized = channel / 255;
+  return normalized <= 0.04045 ? normalized / 12.92 : ((normalized + 0.055) / 1.055) ** 2.4;
+}
+
+function luminance(color: string): number {
+  const channels = hexChannels(color);
+  if (!channels) throw new Error(`Expected a six-digit hex color, received ${color}.`);
+  const [red, green, blue] = channels.map(linear) as [number, number, number];
+  return 0.2126 * red + 0.7152 * green + 0.0722 * blue;
+}
+
+export function contrastRatio(foreground: string, background: string): number {
+  const [lighter, darker] = [luminance(foreground), luminance(background)].sort((a, b) => b - a);
+  return (lighter! + 0.05) / (darker! + 0.05);
+}
+
+export function validateDesignContract(contract: DesignContract = keatingDesignContract): ContractValidationResult {
+  const errors: string[] = [];
+  if (contract.version !== DESIGN_CONTRACT_VERSION) errors.push(`Expected design contract version ${DESIGN_CONTRACT_VERSION}.`);
+  for (const themeName of ["light", "dark"] as const) {
+    const colors = contract.themes[themeName]?.colors;
+    for (const role of COLOR_ROLES) {
+      if (!colors?.[role]) errors.push(`${themeName}.${role} is required.`);
+      else if (!hexChannels(colors[role])) errors.push(`${themeName}.${role} must be a six-digit hex color.`);
+    }
+    if (!colors) continue;
+    for (const requirement of REQUIRED_CONTRAST) {
+      const ratio = contrastRatio(colors[requirement.foreground], colors[requirement.background]);
+      if (ratio < requirement.threshold) {
+        errors.push(`${themeName}.${requirement.foreground}/${requirement.background} contrast ${ratio.toFixed(2)} is below ${requirement.threshold}.`);
+      }
+    }
+  }
+  if (contract.density.minimumTouchTarget !== "2.75rem") errors.push("minimumTouchTarget must remain 2.75rem.");
+  if (contract.motion.reducedMotion !== "none") errors.push("reducedMotion must disable nonessential motion.");
+  if (!(contract.states.disabledOpacity > 0 && contract.states.disabledOpacity < 1)) errors.push("disabledOpacity must be between zero and one.");
+  return { ok: errors.length === 0, errors };
+}
+
+function sorted(value: unknown): unknown {
+  if (Array.isArray(value)) return value.map(sorted);
+  if (!value || typeof value !== "object") return value;
+  return Object.fromEntries(Object.entries(value as Record<string, unknown>).sort(([a], [b]) => a.localeCompare(b)).map(([key, child]) => [key, sorted(child)]));
+}
